  const dead = new DeveloperCouncil({ maxRounds: 0, maxSatisfactionLoops: 1, seatReaskAttempts: 1 });
  let roundZeroCalls = 0;
  dead.askModel = async (model, prompt) => {
    if (String(prompt).includes('Analyze this problem thoroughly')) roundZeroCalls += 1;
    return 'Getting things ready…';
  };
  dead.askForPlanReview = async () => 'SATISFIED';
  const deadDiscussion = await dead.discuss('p', 'c', { models: ['glm-latest'], maxRounds: 0 });
  assert.ok(deadDiscussion.rounds[0].responses[0].error === true, 'a permanently unusable seat stays failed');
  assert.strictEqual(roundZeroCalls, 2, 're-ask must be bounded to one extra try, never open-ended');
  await dead.close();
```

Root cause: The test mock unconditionally counted all `askModel` calls instead of filtering for the round's analysis prompt, causing unrelated model invocations to be counted.

